=== declared-checks.json ===
[
  {
    "id": "cer/template-tokens",
    "severity": "blocking",
    "failureMessage": "the setup contract says: grep for __ afterwards; no token may survive",
    "scanFiles": "/^\\.github\\/workflows\\/[^/]+\\.ya?ml$/",
    "scanTracked": true,
    "matchLines": [
      {
        "match": "/__[A-Z_]+__/",
        "what": "unreplaced template token {match}",
        "fix": "replace it with this repo's value (zip name, bump command, …) per the setup steps"
      }
    ]
  },
  {
    "id": "cer/release-config",
    "severity": "blocking",
    "failureMessage": "the release config is explicit with no defaults — a missing/typo'd key would ship the wrong thing with no signal",
    "checkKeyValueFile": [
      {
        "file": ".github/release.config",
        "keys": ["manifest_path", "package_json_path", "setup_command", "test_command", "ship_paths"],
        "whenMissing": {
          "what": "missing — the release config is required and fully explicit (no defaults)",
          "fix": "create it with the required keys: {keys}"
        },
        "whenLineNotKeyValue": {
          "what": "line is not KEY=value or a # comment: \"{line}\"",
          "fix": "use dotenv syntax — KEY=value, one per line"
        },
        "whenKeyUnknown": {
          "what": "unknown key \"{key}\"",
          "fix": "valid keys: {keys}"
        },
        "whenKeyMissing": {
          "what": "missing required key \"{key}\"",
          "fix": "add \"{key}=...\" (every key is explicit; \"setup_command=\" may be empty to mean no install)"
        }
      }
    ]
  },
  {
    "id": "cer/version-sync",
    "severity": "blocking",
    "failureMessage": "a version that diverges ships the wrong number to the store or refuses to publish",
    "checkParsedFiles": [
      {
        "filesMatching": "/manifest\\.json$/",
        "whereFileContains": "/\"manifest_version\"/",
        "requireEqualFields": {
          "field": "version",
          "inFile": "package.json",
          "atField": "version",
          "whenFileMissing": {
            "what": "missing — the release pipeline builds via npm run build at the repo root",
            "fix": "add the root package.json with version equal to the manifest's"
          },
          "whenUnequal": {
            "what": "manifest version {first} != package.json version {second}",
            "fix": "bump both together — \"bump version\" edits the manifest and package.json in the same change"
          }
        }
      }
    ]
  },
  {
    "id": "cer/release-layout",
    "severity": "blocking",
    "failureMessage": "the privacy page deploys from PRIVACY.md, and the store listing points at that live URL",
    "requirePaths": [
      {
        "path": "dev/build/release/store_artifacts/PRIVACY.md",
        "what": "required release artifact {path} is missing",
        "fix": "create it per the layout in the release standard (adapt from the reference repo)"
      }
    ]
  },
  {
    "id": "cer/readme-sections",
    "severity": "blocking",
    "failureMessage": "every extension repo documents install and release the same way, from the standard template",
    "fix": "copy it from the README template in the release standard and fill in the repo values",
    "scanFiles": "README.md",
    "scanIgnoringMarkdownFences": true,
    "whenMissing": {
      "what": "missing",
      "fix": "add a README with the standard Install and Releasing sections"
    },
    "checkEachFile": [
      {
        "require": "/^##\\s+Install\\b/m",
        "what": "missing the standard \"## Install\" section"
      },
      {
        "require": "/^##\\s+Releasing\\b/m",
        "what": "missing the standard \"## Releasing\" section"
      }
    ]
  },
  {
    "id": "cer/permission-added-store-issue",
    "severity": "advisory",
    "failureMessage": "the store requires a written justification per permission and blocks publishing the new version until the dashboard carries it; that step is manual, so a proactive issue beats the reactive publish failure",
    "scope": "work",
    "forbidAddedValueInArray": [
      {
        "filesMatching": "/(^|\\/)manifest\\.json$/",
        "whereFileContains": "/\"manifest_version\"/",
        "atFields": ["permissions", "host_permissions", "optional_permissions", "optional_host_permissions"],
        "what": "this change adds the \"{value}\" permission",
        "fix": "open a tracking issue for the manual Chrome Web Store dashboard step: the Privacy-practices tab needs a written justification for \"{value}\" before the next publish can ship"
      }
    ]
  },
  {
    "id": "cer/privacy-permission-alignment",
    "severity": "blocking",
    "failureMessage": "the deployed privacy policy must disclose everything the extension can access; an undisclosed permission is a store-review and trust failure",
    "extractValueSets": [
      {
        "setName": "requestedPermissions",
        "fromParsedFilesMatching": "/(^|\\/)manifest\\.json$/",
        "whereFileContains": "/\"manifest_version\"/",
        "valuesOfArraysAtFields": ["permissions", "host_permissions", "optional_permissions", "optional_host_permissions"],
        "whenSetEmpty": "assertNothing"
      }
    ],
    "requireIndexCoverage": [
      {
        "eachValueOfSet": "requestedPermissions",
        "indexFile": "dev/build/release/store_artifacts/PRIVACY.md",
        "coveredByText": "{value}",
        "whenIndexFileAbsent": "assertNothing",
        "anchorFindingsAt": "indexFile",
        "what": "manifest requests \"{value}\" but the privacy document does not mention it",
        "fix": "disclose what \"{value}\" accesses in PRIVACY.md, so the deployed privacy policy reflects what the extension can reach"
      }
    ]
  }
]
=== store-release task.mjs ===
// chrome-extension-release task: store-release — the pack-contributed release
// trigger (per-project-scheduling DESIGN §6). STRUCTURAL Stage 2: `model: 'none'`
// means the whole decision is code and there is NO agent phase —
// the executor runs `worker.mjs` as code-work. This task ABSORBS the
// release workflow's own independent 00:30 cron: the workflow becomes push +
// workflow_dispatch only, and this task is the one place that fires its daily
// leg, so the scheduler stays the repo's only cron (DESIGN §3, decision §11.6).
//
// Self-contained (imports nothing): the whole contract is this default export.

const norm = (v) => String(v ?? '').replace(/^v/, '').trim(); // compare tags/versions modulo a leading 'v'

export default {
  id: 'store-release',
  frequency: 'daily',              // the 04:00 anchor (DESIGN §2) — replaces the workflow's own 00:30 cron
  precondition_signals: ['release', 'commits'],
  agent_model: 'none',                   // pure code — no agent (task-code-work DESIGN §4)
  expected_outcome: 'none',                 // it only TRIGGERS the gated publish workflow; publishing stays behind that workflow's own guards
  code_work: 'node worker.mjs',      // the executor runs this as code_work (cwd = this task dir) — DESIGN §3
  code_work_timeout: 120,            // the dispatch is a quick REST call; a tight bound (the await-the-run Stage 2 would widen it)

  // Detect a deployable change since the last release, entirely in code:
  //   (a) the manifest version has advanced past the latest published release
  //       (an unreleased bump — the same signal the old run_daily gate used), OR
  //   (b) a substantive default-branch commit landed in the window (a real ship).
  // Ship-path precision (the daily job's `ship_paths` filter) is NOT re-derived
  // here — .github/release.config isn't in a precondition's scope — because the
  // dispatched daily workflow does the authoritative shipped-file diff vs the
  // latest release tag and no-ops when nothing shippable moved. So the
  // precondition is the cheap pre-filter; the workflow is the exact gate.
  precondition(signals) {
    const rel = signals.release ?? {};
    const shipped = norm(rel.manifestVersion);
    const released = norm(rel.latestTag);
    const manifestAhead = shipped !== '' && shipped !== released;
    const substantive = signals.commits?.substantiveChange === true;

    if (manifestAhead) {
      return { run: true, reason: released ? `manifest ${shipped} is ahead of released ${released}` : `manifest ${shipped}, no release yet` };
    }
    if (substantive) {
      return { run: true, reason: 'substantive default-branch change in the window — let the daily release workflow diff shipped files' };
    }
    return { run: false, reason: 'manifest matches the latest release and no substantive change in the window' };
  },
};

